def check_modal_compliance(text, tonic_midi=63):
    notes = get_all_notes(text)
    nahawand_pcs = {0, 2, 3, 5, 7, 8, 10}
    # 0: D#, 2: E#, 3: F#, 5: G#, 7: A#, 8: B, 10: C#
    # color: 11 (raised 7: D)
    issues = []
    for v in ['Vocal', 'Ins']:
        v_notes = [ev for ev in notes[v] if ev[0] == 'n']
        for ev in v_notes:
            deg = (ev[3] - tonic_midi) % 12
            if deg not in nahawand_pcs and deg != 11:
                issues.append((v, ev))
    print("Modal issues:", len(issues))
    return len(issues) == 0

